_id varchar(100), goodreads_id varchar(100), google_id varchar(100), hardcover_book_id varchar(100), hardcover_id varchar(100), lubimyczytac_id varchar(100), ranobedb_id varchar(100), narrator varchar(500), description TEXT, embedding_vector TEXT, publisher varchar(255), search_text TEXT, series_name varchar(255), subtitle varchar(255), title varchar(255) not null, primary key (book_id));
